import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;


// Предполагается, что у нас есть в БД таблица, например:
// CREATE TABLE storage (
//     id INT GENERATED BY DEFAULT AS IDENTITY (START WITH 0) PRIMARY KEY,
//     data TEXT NOT NULL
// );

interface Storage {
    void save(String data);
    String retrieve(int id);
}

class PostgresStorage implements Storage {
    private final Connection connection;

    public PostgresStorage(Connection connection) {
        this.connection = connection;
    }

    @Override
    public void save(String data) {
        String sql = "INSERT INTO storage (data) VALUES (?)";
        try (PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, data);
            statement.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Ошибка при сохранении данных в БД", e);
        }
    }

    @Override
    public String retrieve(int id) {
        String sql = "SELECT data FROM storage WHERE id = ?";
        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setInt(1, id);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return rs.getString("data");
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Ошибка при получении данных из БД", e);
        }
        return null;
    }
}

public class Main {
    public static void main(String[] args) {
        String url = "jdbc:postgresql://localhost:5432/mydb";
        String user = "postgres";
        String password = "password";

        try (Connection connection = DriverManager.getConnection(url, user, password)) {
            Storage dbStorage = new PostgresStorage(connection);

            // Сохраняем несколько строк
            dbStorage.save("Первая строка в Postgres");
            dbStorage.save("Вторая строка в Postgres");

            // Извлекаем их по id
            System.out.println("Запись 0: " + dbStorage.retrieve(0));
            System.out.println("Запись 1: " + dbStorage.retrieve(1));
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
